    "question": "A 35-year-old female undergoes allogeneic renal transplantation for end-stage diabetic nephropathy. Three weeks post-surgery, despite donor HLA matching, her serum creatinine rises sharply, and kidney biopsy demonstrates intense interstitial infiltration by CD8+ cytotoxic T-lymphocytes causing graft tubulitis. What immunological mechanism explains this acute graft rejection?",
