    "question": "A 32-year-old IV drug user presents with persistent generalized lymphadenopathy, recurrent oral candidiasis (fungal thrush), chronic watery diarrhea, and a 12 kg weight loss. Laboratory evaluation reveals an absolute CD4+ T cell count of 85 cells/microlitre. Sputum microscopy reveals acid-fast bacilli confirmed as Mycobacterium avium complex. What is the definitive diagnosis and pathophysiological rationale?",
